<?php include "auth.php"; include "../database.php"; if(isset($_GET['id'],$_GET['status'])){$id=intval($_GET['id']);$st=$_GET['status'];if(in_array($st,['Confirmed','Cancelled'])){$s=$conn->prepare("UPDATE booking SET status=? WHERE booking_id=?");$s->bind_param("si",$st,$id);$s->execute();}header("Location: bookings.php");exit;} $r=$conn->query("SELECT b.*,u.name customer_name,u.email,sp.name provider_name,sp.service_type FROM booking b JOIN users u ON b.user_id=u.user_id JOIN service_provider sp ON b.provider_id=sp.provider_id ORDER BY b.booking_id DESC"); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Private Bookings</title><link rel="stylesheet" href="../style.css"></head><body><main class="container"><h1>Private Booking Management</h1><p>Only the admin can access this page.</p><a class="btn secondary" href="index.php">Dashboard</a><table><tr><th>ID</th><th>Customer</th><th>Email</th><th>Provider</th><th>Service</th><th>Date</th><th>Time</th><th>Status</th><th>Action</th></tr><?php while($b=$r->fetch_assoc()):?><tr><td><?=$b['booking_id']?></td><td><?=htmlspecialchars($b['customer_name'])?></td><td><?=htmlspecialchars($b['email'])?></td><td><?=htmlspecialchars($b['provider_name'])?></td><td><?=htmlspecialchars($b['service_type'])?></td><td><?=$b['booking_date']?></td><td><?=$b['start_time']?></td><td><?=$b['status']?></td><td><?php if($b['status']==='Pending'):?><a class="btn" href="?id=<?=$b['booking_id']?>&status=Confirmed">Confirm</a> <a class="btn secondary" href="?id=<?=$b['booking_id']?>&status=Cancelled">Cancel</a><?php endif;?></td></tr><?php endwhile;?></table></main></body></html>